// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: mbrola:tr1
window.VOICE = {"engine":"mbrola:tr1","gain":1.25,"lines":[{"id":"open-title","say":"Birinci kapı. Var ve yok: iki simgeli bir evren.","at":3.8,"dur":4.082,"marks":[0,1.491,2.687]},{"id":"fires-one","say":"Dağın tepesinde bir ateş yanıyor.","at":9.582,"dur":2.018,"marks":[0]},{"id":"fires-meaning","say":"Ne anlama geldiği önceden kararlaştırılmıştı: düşman sınırı geçti.","at":12.051,"dur":4.628,"marks":[0,3.173]},{"id":"fires-relay","say":"Karşı tepedeki nöbetçi, ateşi görür görmez kendi ateşini yakardı; ondan ötekisi, ondan berikisi.","at":17.779,"dur":7.387,"marks":[0,1.965,4.972,6.305]},{"id":"fires-race","say":"Böylece haber, atlının günlerce süren yolculuğunu, saatlere indirirdi.","at":26.266,"dur":4.919,"marks":[0,1.286,3.701]},{"id":"fires-question","say":"Peki, ateş tam olarak ne söylüyordu?","at":32.685,"dur":2.652,"marks":[0,0.798]},{"id":"fires-answer","say":"Aslında tek bir şey: oldu.","at":36.337,"dur":2.187,"marks":[0,1.774]},{"id":"two-split","say":"Yanıyorsa oldu, yanmıyorsa olmadı. İki durum: var ve yok.","at":40.724,"dur":4.988,"marks":[0,1.349,3.104,4.242]},{"id":"two-levels","say":"Peki ateşle elli ayrı haber verilseydi? Biraz yanarsa asker, yarı yanarsa gemi, gürül gürül yanarsa savaş.","at":46.713,"dur":7.815,"marks":[0,3.022,4.689,6.184]},{"id":"two-weather","say":"Şimdi yağmuru, sisi ekleyin. Yorgun bir nöbetçi, ateşin biraz mı, yarı mı yandığını kestiremez. Ama yanıyor mu, yanmıyor mu; bunu her zaman görür.","at":55.528,"dur":11.907,"marks":[0,1.341,2.904,4.566,5.955,8.214,9.424,10.615]},{"id":"two-quote","say":"İki durum arasında yanılmak, elli durum arasında yanılmaktan çok daha güçtür.","at":68.834,"dur":5.066,"marks":[0,2.019]},{"id":"two-icons","say":"Bu tek cümle, telefonun, televizyonun, bankadaki hesabın ve bu kitabın temelidir.","at":76,"dur":6.139,"marks":[0,1.21,2.282,3.502]},{"id":"why-volt","say":"Bugünün makineleri de ateş yerine elektrik kullanır. Bir teldeki elektriğin ne kadar güçlü ittiğini, volt denen birimle ölçeriz.","at":83.439,"dur":8.617,"marks":[0,3.743,6.946]},{"id":"why-wobble","say":"Ama bu değer hiç yerinde durmaz: sıcaklık değişir, kablonun direnci artar, komşu devreden parazit gelir. Tam üç virgül yetmiş dört volt dersiniz, bir saniye sonra yanılırsınız.","at":92.506,"dur":12.887,"marks":[0,2.333,3.939,5.733,8.175,11.092]},{"id":"why-threshold","say":"Ama şunu sormak kolaydır: akım var mı, yok mu? Makine ortaya eşik denen bir çizgi çeker. Üstündeyse var, altındaysa yok; değer biraz oynasa da cevap değişmez.","at":106.493,"dur":12.556,"marks":[0,2.114,3.225,4.369,7.591,8.963,10.377]},{"id":"why-code","say":"Akım var, bir. Akım yok, sıfır.","at":119.498,"dur":3.46,"marks":[0,1.012,1.958,2.917]},{"id":"why-bit","say":"Bu iki değerin her birine bit denir. Bit, bilişimin atomudur: bölünemeyen en küçük bilgi parçası.","at":125.558,"dur":7.26,"marks":[0,2.662,3.31,4.973]},{"id":"why-pairs","say":"Tek başına çok az şey anlatır: evet ya da hayır, açık ya da kapalı.","at":133.268,"dur":4.971,"marks":[0,2.407,3.788]},{"id":"lamps-one","say":"Bir lamba kadar: sönükse sıfır, yanıyorsa bir. Ama bitleri yan yana dizince, bir şey olur.","at":139.439,"dur":7.35,"marks":[0,1.485,2.912,4.454,6.493]},{"id":"lamps-two","say":"İki lamba düşünün. Kaç farklı durum kurabilirsiniz? Kapalı kapalı, kapalı açık, açık kapalı, açık açık. Dört.","at":147.689,"dur":10.028,"marks":[0,1.823,4.587,5.878,6.998,8.281,9.632]},{"id":"lamps-three","say":"Üç lamba? Sekiz durum. Çünkü yeni lamba sönükken, eski dört durum aynen kurulur; yanarken, aynı dört durum bir kez daha. Dört artı dört, sekiz.","at":158.617,"dur":12.59,"marks":[0,1.389,2.857,4.952,7.304,8.366,10.79,12.095]},{"id":"lamps-four","say":"Dört lamba? On altı. Her yeni lamba, olasılıkları ikiye katlar.","at":172.706,"dur":5.639,"marks":[0,1.486,2.626,3.96]},{"id":"lamps-table","say":"Katlamayı sürdürün: otuz iki, altmış dört, yüz yirmi sekiz, iki yüz elli altı. Sekiz lamba, iki yüz elli altı durum.","at":179.245,"dur":9.564,"marks":[0,1.664,2.65,3.869,5.237,6.916,8.181]},{"id":"lamps-big","say":"Otuz iki lambada dört milyarı aşar. Sezgimiz en çok burada yanılır.","at":189.259,"dur":4.712,"marks":[0,2.759]},{"id":"lamps-byte","say":"Sekiz bitlik bu öbeğe bayt denir.","at":195.671,"dur":2.007,"marks":[0]},{"id":"lamps-values","say":"Her lambanın bir değeri vardır: sağdan sola bir, iki, dört, sekiz, ve böyle, yüz yirmi sekize kadar. Yanan lambaların değerleri toplanır.","at":198.678,"dur":11.332,"marks":[0,2.323,3.756,4.495,5.243,6.089,7.03,9.116]},{"id":"lamps-range","say":"Hepsi sönükse sıfır, hepsi yanarsa iki yüz elli beş. Bir bayt, bu aralıkta bir sayı tutar.","at":210.46,"dur":6.773,"marks":[0,1.791,4.283,5.195]},{"id":"lamps-letters","say":"Bu, bütün harflere, rakamlara ve işaretlere yeter. Bir bayt, kabaca bir harftir.","at":218.833,"dur":6.746,"marks":[0,0.647,2.066,4.619,5.53]},{"id":"glossary-rows","say":"Kilo, kilogramdaki gibi bin demektir; her basamak bin kat büyür. Kilobayt kısa bir mektup, megabayt bir şarkı, gigabayt bir film, terabayt bir kütüphane.","at":226.779,"dur":12.07,"marks":[0,0.769,3.195,5.496,7.417,9.092,10.61]},{"id":"glossary-compare","say":"Bu bölümün otuz bin harflik metni, otuz kilobayttır. Tek bir fotoğraf ise, bunun yüz katı.","at":239.849,"dur":6.851,"marks":[0,2.43,4.177,5.87]},{"id":"letters-question","say":"Makine yalnızca sıfır ile bir biliyorsa, ekrandaki A harfi nedir?","at":247.8,"dur":4.301,"marks":[0,2.755]},{"id":"letters-answer","say":"Makinenin içinde A harfi diye bir şey yoktur; altmış beş sayısı vardır.","at":253.8,"dur":4.925,"marks":[0,3.2]},{"id":"letters-encoding","say":"İnsanlar anlaştı: her harfe bir numara. Buna karakter kodlaması denir.","at":259.725,"dur":5.472,"marks":[0,1.59,3.537]},{"id":"letters-cards","say":"A altmış beş, be altmış altı, küçük a doksan yedi, boşluk bile otuz iki.","at":265.648,"dur":5.699,"marks":[0,1.245,2.607,4.317]},{"id":"letters-merhaba","say":"Bellekte merhaba yazmaz; şu yazar: yetmiş yedi, altmış dokuz, seksen iki, yetmiş iki, altmış beş, altmış altı, altmış beş.","at":272.346,"dur":11.331,"marks":[0,1.98,3.089,4.333,5.606,6.841,8.065,9.255,10.489]},{"id":"letters-bits","say":"Onlar da lambalardaki gibi, var yok dizileri olarak durur: altmış beş, altmış dört artı bir.","at":284.127,"dur":6.809,"marks":[0,2.012,4.232,5.423]},{"id":"letters-fonts","say":"Harfin şeklini yazı tipi çizer; makine yalnızca numarasını bilir.","at":292.536,"dur":4.52,"marks":[0,2.51]},{"id":"turkish-grid","say":"Bu anlaşmayı İngilizce konuşanlar yaptı. Yirmi altı harf için yüz yirmi sekiz yer ayırdılar; içine sığdı, arttı bile.","at":298.156,"dur":8.539,"marks":[0,3.07,6.588,7.804]},{"id":"turkish-half","say":"Oysa bir bayt iki yüz elli altı yer sunar; öteki yarı boş kaldı.","at":307.645,"dur":4.211,"marks":[0,2.838]},{"id":"turkish-letters","say":"Türkçenin çe, yumuşak ge, ı, büyük i, ö, şe ve ü harfleri ise o listede yoktu.","at":312.806,"dur":6.967,"marks":[0,1.384,2.583,3.156,4.107,4.686]},{"id":"turkish-place","say":"Her ülke, boş yarıya kendi harflerini koydu; ama herkes, farklı yere.","at":320.723,"dur":5.68,"marks":[0,1.029,3.674,4.817]},{"id":"turkish-mojibake","say":"Belge gönderince yola harf değil, sayı çıkar. Sizde iki yüz kırk, yumuşak gedir; karşıdaki sözlükte ise bambaşka bir harf.","at":328.004,"dur":9.575,"marks":[0,2.376,3.819,5.407,6.86]},{"id":"turkish-agreement","say":"Kimse art niyetli değildi; yalnızca sözlükler farklıydı.","at":338.579,"dur":4.094,"marks":[0,2.076]},{"id":"turkish-unicode","say":"Çözüm, bütün yazıları tek bir dev listede toplamaktı: Yunikod. Türk harfleri de, Çin yazısı da, gülen yüzler de orada.","at":343.673,"dur":9.291,"marks":[0,0.897,4.08,5.239,6.717,8.004]},{"id":"turkish-codepoint","say":"Artık yumuşak ge, her yerde aynı numaradır: iki yüz seksen yedi.","at":353.414,"dur":4.844,"marks":[0,1.563,3.5]},{"id":"turkish-master","say":"Teknolojideki sorunların çoğu, teknik değil, anlaşma sorunudur. İki taraf aynı sözlüğe bakmıyorsa, kabloların hiçbir suçu yoktur.","at":359.257,"dur":9.874,"marks":[0,2.306,3.531,5.344,7.846]},{"id":"hex-blur","say":"Uzun bit dizilerini okumak göze işkencedir. Bu yüzden bir kısaltma kullanılır: onaltılık düzen.","at":371.031,"dur":6.832,"marks":[0,3.193,5.774]},{"id":"hex-digits","say":"Dört lambanın on altı durumu vardı; her birine tek bir simge gerekir. Rakamlarımız ise on tane, sıfırdan dokuza; kalan altısı için harfler kullanılır: A on, be on bir, ve böyle, fe on beşe kadar.","at":378.863,"dur":15.26,"marks":[0,2.519,5.156,7.055,8.664,11.465,12.18,13.18,14.121]},{"id":"hex-split","say":"Diziyi dörder bölün. Dört lambanın değerleri sekiz, dört, iki, bir. İlk öbekte sekiz, dört ve bir yanıyor: on üç, yani de. İkincide dört ile iki: altı. Kısaca, de altı.","at":395.123,"dur":15.904,"marks":[0,1.845,4.121,4.869,5.609,6.554,8.051,9.739,10.525,11.623,13.457,14.463,15.378]},{"id":"hex-colors","say":"Web sayfalarında renkler böyle yazılır. Ekrandaki her renk, kırmızı, yeşil ve mavi ışığın karışımıdır; koddaki üç çift, bu üç ışığın miktarıdır.","at":412.927,"dur":11.19,"marks":[0,3.04,4.652,5.569,8.216,9.67]},{"id":"hex-red","say":"Fe fe en çok, yani iki yüz elli beş; sıfır sıfır, hiç. Kırmızı sonuna kadar açık, öbürleri kapalı: katıksız kırmızı. Hepsi kapalı siyah, hepsi açık beyaz.","at":424.566,"dur":13.161,"marks":[0,1.197,2.931,4.215,5.201,7.158,8.666,10.453,12.033]},{"id":"hex-phone","say":"Yeni bir bilgi değil, aynı bilginin kolay okunan kılığıdır; tıpkı telefon numarasını bölerek yazmak gibi.","at":439.227,"dur":6.982,"marks":[0,1.551,4.242]},{"id":"numbers-photo","say":"Bir fotoğraf, sık dokunmuş bir kumaş gibidir: yakından bakınca minicik kareler görürsünüz, pikseller.","at":447.31,"dur":7.632,"marks":[0,1.245,3.746,6.854]},{"id":"numbers-pixel","say":"Her pikselin üç sayısı vardır: kırmızının, yeşilin ve mavinin miktarı. Milyonlarca piksel, milyonlarca üçlü sayı.","at":455.392,"dur":9.097,"marks":[0,2.469,3.596,6.017,7.659]},{"id":"numbers-sound","say":"Ses, havadaki basınç dalgasıdır. Saniyede on binlerce kez ölçülür; her ölçüm bir sayıdır. Bu sayılar hızla çalınınca, kulak aynı sesi duyar.","at":465.489,"dur":11.206,"marks":[0,0.754,3.23,5.758,7.786,9.821]},{"id":"numbers-video","say":"Video, saniyede yirmi beş fotoğraftır; göz onları akan bir hareket olarak görür.","at":477.595,"dur":5.713,"marks":[0,0.812,3.276]},{"id":"numbers-sensors","say":"Sıcaklık, nem, mesafe, kalp atışı; hepsini sensörler ölçüp sayıya çevirir.","at":484.308,"dur":6.525,"marks":[0,1.033,1.766,2.734,3.994]},{"id":"numbers-statement","say":"Ortak nokta şudur: ölçülebilen her şey sayıya çevrilebilir; sayıya çevrilen her şey, işlenebilir, saklanabilir, iletilebilir.","at":491.833,"dur":10.029,"marks":[0,1.702,4.712,6.678,7.895,9.196]},{"id":"numbers-danger","say":"Bilişim çağının bütün gücü de, bütün tehlikesi de, bu tek cümlede saklıdır.","at":502.312,"dur":5.364,"marks":[0,2.23,3.817]},{"id":"numbers-watched","say":"Çünkü bu cümle, insan için de geçerlidir: nerede olduğunuz, kiminle konuştuğunuz, neye baktığınız, neyi kaç saniye izlediğiniz.","at":509.477,"dur":9.37,"marks":[0,1.349,3.43,4.713,6.298,7.639]},{"id":"numbers-power","say":"Ölçmek, güçtür.","at":520.347,"dur":1.578,"marks":[0,0.953]},{"id":"numbers-question","say":"Ve her güç gibi, kimin elinde olduğu sorusunu doğurur.","at":522.375,"dur":3.507,"marks":[0,1.419]},{"id":"close-end","say":"Var ve yok.","at":528.082,"dur":0.746,"marks":[0]}],"audio":""};
